def runs(s, minaa):
    out=[]
    for f in range(3):
        i=f
        while i+2 < len(s):
            if s[i:i+3] in STOPS:
                i+=3; continue
            j=i
            while j+2<len(s) and s[j:j+3] not in STOPS: j+=3
            aa=(j-i)//3
