def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def total_stops(s):
    tot=0
    for strand in (s, rc(s)):
        for f in range(3):
            tot += sum(1 for i in range(f,len(strand)-2,3) if strand[i:i+3] in STOPS)
    return tot

def max_antisense_overlap(s, minaa=250):
    """longest ORF per frame per strand; then max overlap length between + and - ORFs both >= minaa"""
    plus={}; minus={}
    sr=rc(s)
    for f in range(3):
        cur=0; best=(0,0,0)
        for i in range(f,len(s)-2,3):
            if s[i:i+3] in STOPS:
                if cur>best[2]: best=(i-cur*3, i, cur)
                cur=0
            else: cur+=1
        if cur>best[2]: best=(len(s)-3-cur*3, len(s), cur)
        plus[f]=best
        cur=0; best=(0,0,0)
        for i in range(f,len(sr)-2,3):
            if sr[i:i+3] in STOPS:
                if cur>best[2]: best=(i-cur*3,i,cur)
                cur=0
            else: cur+=1
        if cur>best[2]: best=(len(sr)-3-cur*3,len(sr),cur)
        minus[f]=best
    # convert minus ORF (rc coords [a,b)) to plus coords: plus [len-b, len-a)
    best_ov=0
    for f1 in range(3):
        a1,b1,n1=plus[f1]
        if n1<minaa: continue
        for f2 in range(3):
            a2,b2,n2=minus[f2]
            if n2<minaa: continue
            x,y = L-b2, L-a2   # plus coords of minus ORF
            ov = min(b1,y)-max(a1,x)
            if ov>best_ov: best_ov=ov
    return best_ov

